SELECT addDays(toDate(toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0)), throwIf(ifNull((toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) < toDate32('1970-01-01')) OR (toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) > toDate32('2149-06-06')), 0), 'typedhouse_date_out_of_range')) AS `week`, avg(`__typedhouse_input`.`market_stock_total`) AS `stock`, quantile({p0:Float64})(`__typedhouse_input`.`market_lead_time_p50_days`) AS `leadDays` FROM `metric_group_ots_component_market_availability` AS `__typedhouse_input` FINAL WHERE `__typedhouse_input`.`tenantId` = {p1:String} AND `__typedhouse_input`.`entityId` = {p2:String} GROUP BY addDays(toDate(toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0)), throwIf(ifNull((toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) < toDate32('1970-01-01')) OR (toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) > toDate32('2149-06-06')), 0), 'typedhouse_date_out_of_range')) ORDER BY `week` ASC SETTINGS enable_extended_results_for_datetime_functions = 1
